package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by category and price range
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Basic input sanitization - strip obvious dangerous characters
	category = strings.ReplaceAll(category, ";", "")
	category = strings.ReplaceAll(category, "--", "")

	// Build query with parameterized category but dynamic sort
	baseQuery := "SELECT id, name, price, description FROM products WHERE category = $1"

	if minPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= %s", minPrice)
	}
	if maxPrice != "" {
		baseQuery += fmt.Sprintf(" AND price <= %s", maxPrice)
	}

	// Sort field validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField != "" && allowedSorts[sortField] {
		baseQuery += " ORDER BY " + sortField
	} else {
		baseQuery += " ORDER BY name"
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		// Note: not escaping JSON properly - potential issue but not the main vuln
		line := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)
		w.Write([]byte(line))
		first = false
	}
	w.Write([]byte("\n]"))
}

// healthHandler for load balancer health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
